/* @autogenerated */
import { Observable } from 'rxjs';
import { Acl } from '@shared/data/acl/acl.model';
import { Slide } from '@shared/data/repository/provider/repository-provider.interface';
import { ImportColumn } from '@shared/toolkit/entity-import/entity-import.model';

/** Traduce referencias (`$ref`) de otra entidad al texto con el que se muestran y se vuelven a importar. */
export interface ExportReference {
  /** Texto de cada referencia pedida; las que falten se exportan con su `$ref`. */
  names(refs: string[]): Observable<Record<string, string>>;
}

/** Operaciones que la exportación necesita del repositorio. Cada observable debe emitir una vez. */
export interface ExportSource<T> {
  /** ACL genérico: las columnas que oculta no se exportan. */
  acl(): Observable<Acl>;
  /** Página de elementos que coinciden con el filtro; `next` se mezcla con el filtro para pedir la siguiente. */
  list(filter: any): Observable<Slide<T>>;
}

/**
 * Configuración de la exportación de una entidad. Las columnas son las de la importación: el Excel exportado
 * se puede editar y volver a importar.
 */
export interface ExportDefinition<T> {
  /** Identifica la entidad en el nombre del fichero (`identity.user`). */
  name: string;
  /** Scope de transloco con las etiquetas de los campos. */
  scope: string;
  columns: ImportColumn[];
  /** Campos que nunca se exportan (p. ej. la contraseña). */
  sensitive?: string[];
  references?: { [field: string]: ExportReference };
  source: ExportSource<T>;
  /** Elementos por petición; por defecto `EXPORT_PAGE_SIZE`. */
  pageSize?: number;
  /** Máximo de filas del Excel; por defecto `EXPORT_LIMIT`. */
  limit?: number;
}

/** Columna que se escribe, con su cabecera ya traducida. */
export interface ExportColumn extends ImportColumn {
  text: string;
  /** Etiqueta traducida de cada valor de un `enum`. */
  optionTexts?: Record<string, string>;
}
